const spec={place:['Number',0,99,23],fraction:['Selected eighths',0,8,4],equation:['Value of x',0,8,4],area:['Width in units',1,8,4],function:['Input x',0,8,3],probability:['Favorable die faces',0,6,3],particles:['State: 0 solid, 1 liquid, 2 gas',0,2,0],force:['Net force in newtons',0,8,4],energy:['Useful energy out of 10',0,10,6],cells:['Ideal doublings',0,4,1],ohm:['Voltage in volts',1,12,6],earth:['Hours of rotation',0,24,6],maximum:['Third value',0,9,5],variable:['Amount added to 4',0,9,3],condition:['Age tested against age < 10',0,14,9],loop:['Iteration limit',0,8,4],search:['Target in [2,4,6,8]',1,9,6],binary:['Unsigned integer',0,15,6],memory:['Allocated units out of 16',0,16,6],network:['Delay per link in milliseconds',1,8,3],database:['Minimum score',0,9,5],permission:['Owner matches: 0 no, 1 yes',0,1,0],accuracy:['Correct predictions out of 10',0,10,8],design:['Prototype cost; budget 10',1,14,8],torque:['Force at a 2 m perpendicular arm',0,8,3],series:['Added series resistance; fixed 2 Ω',1,10,4],sensor:['Distance in centimetres',0,8,3],control:['Update number; target 10, gain 0.5',0,6,1],automation:['Moisture; pump starts below 30',0,60,20],sequence:['Term number',1,10,4],logic:['Truth assignment: 0 FF, 1 FT, 2 TF, 3 TT',0,3,2],flow:['Value compared with 5',0,10,7],data:['Third observation with 2 and 4',1,24,6],sampling:['Additional observations of value 4',0,8,2],optimization:['Weight on cost',0,5,2]};
export const modelSpec=id=>{const a=spec[id];if(!a)throw Error('Unknown model '+id);return {label:a[0],min:a[1],max:a[2],initial:a[3]}};
export function computeModel(id,x){const s=modelSpec(id);if(!Number.isFinite(x)||x<s.min||x>s.max)throw Error('Model input out of range');let values=[],labels=[],result,caption,formula;
 switch(id){
 case'place':values=[Math.floor(x/10),x%10];labels=['tens','ones'];result=x;caption=`${values[0]} bundles of ten and ${values[1]} single ones make ${x}.`;formula=`${values[0]} × 10 + ${values[1]} = ${x}`;break;
 case'fraction':values=[x,8-x];labels=['selected','remaining'];result=x/8;caption=`${x} of 8 equal pieces are selected. The same whole is always used.`;formula=`${x}/8 = ${result}`;break;
 case'equation':values=[2*x,3,2*x+3];labels=['two bags','extra blocks','total'];result=2*x+3;caption=`Each bag has ${x} blocks. Two bags plus three loose blocks balance ${result} blocks.`;formula=`2 × ${x} + 3 = ${result}`;break;
 case'area':values=[x,3,x*3];labels=['width','height','area'];result=x*3;caption=`A rectangle ${x} units wide and 3 units high covers ${result} unit squares. Its perimeter is ${2*(x+3)} units.`;formula=`A=${x}×3=${result}; P=2(${x}+3)=${2*(x+3)}`;break;
 case'function':values=[x,2*x+1];labels=['input','output'];result=2*x+1;caption=`The machine doubles ${x}, then adds one. Its output is ${result}.`;formula=`f(${x}) = 2(${x}) + 1 = ${result}`;break;
 case'probability':values=[x,6-x];labels=['favorable','other'];result=x/6;caption=`${x} of 6 equally likely faces count as success. Probability is ${(result*100).toFixed(1)}%. This is a model, not a prediction of the next roll.`;formula=`P=${x}/6`;break;
 case'particles':values=Array(12).fill(1);labels=['solid','liquid','gas'];result=x;caption=['Particles stay near fixed relative positions and can vibrate.','Particles remain close but can move past one another.','Particles are widely separated and move throughout the container.'][x];formula='Qualitative particle model; positions are illustrative, not to scale.';break;
 case'force':values=[x,2,x/2];labels=['net force N','mass kg','acceleration m/s²'];result=x/2;caption=`A ${x} N net push on a 2 kg cart changes its velocity by ${result} metres per second each second.`;formula=`a=F/m=${x}/2=${result} m/s²`;break;
 case'energy':values=[x,10-x];labels=['useful transfer','other transfer'];result=x*10;caption=`Of 10 energy units, ${x} go to the intended task and ${10-x} to other changes. Total energy remains 10.`;formula=`η=${x}/10 ×100%=${result}%`;break;
 case'cells':values=[1,2**x];labels=['initial cells','modeled cells'];result=2**x;caption=`One cell doubles ${x} times in this ideal model, giving ${result}. Real growth is regulated and resource-limited.`;formula=`N=1×2^${x}=${result}`;break;
 case'ohm':values=[x,3,x/3];labels=['voltage V','resistance Ω','current A'];result=x/3;caption=`At ${x} V across an ideal 3 Ω resistor, current is ${result.toFixed(2)} A. This virtual calculation is not a safety rating.`;formula=`I=V/R=${x}/3`;break;
 case'earth':values=[x,24-x];labels=['elapsed hours','rest of day'];result=x*15;caption=`In a 24-hour solar-day model, ${x} hours corresponds to ${result} degrees of rotation. Time zones can differ from local solar time.`;formula=`θ=${x} × 360/24=${result}°`;break;
 case'maximum':values=[3,7,x];labels=['first','second','third'];result=Math.max(...values);caption=`Compare 3, 7, and ${x}. Keep the largest seen so far. The maximum is ${result}.`;formula=`max(3,7,${x})=${result}`;break;
 case'variable':values=[4,x,4+x];labels=['old value','added value','new value'];result=4+x;caption=`The score starts at 4. Add ${x}, then store ${result} as the new score.`;formula=`score = 4 + ${x}; // ${result}`;break;
 case'condition':values=[x,10];labels=['tested age','excluded boundary'];result=x<10?1:0;caption=`For age ${x}, the condition age < 10 is ${result?'true: take the child-ticket branch':'false: take the other branch'}.`;formula=`${x} < 10 → ${!!result}`;break;
 case'loop':values=Array.from({length:x},(_,i)=>i+1);labels=values.map((_,i)=>'i='+i);result=x;caption=`The loop runs ${x} times with counter values ${Array.from({length:x},(_,i)=>i).join(', ')||'(none)'}. It stops before counter ${x}.`;formula=`for (let i=0; i<${x}; i++)`;break;
 case'search':values=[2,4,6,8];labels=values.map((_,i)=>'index '+i);result=values.indexOf(x);caption=`Searching for ${x} ${result<0?'checks all four items and finds no match':`finds index ${result} after ${result+1} comparisons`}.`;formula=`[2,4,6,8].indexOf(${x}) = ${result}`;break;
 case'binary':values=[8,4,2,1].map(w=>x&w?w:0);labels=['8','4','2','1'];result=x;caption=`The on/off pattern ${x.toString(2).padStart(4,'0')} represents ${x}. Add the active place weights.`;formula=values.join(' + ')+' = '+x;break;
 case'memory':values=[x,16-x];labels=['allocated','free'];result=16-x;caption=`The simplified memory has 16 units. ${x} are allocated; ${result} remain free. Virtual-memory behavior is omitted.`;formula=`free=16−${x}=${result}`;break;
 case'network':values=[x,x,x];labels=['link 1 ms','link 2 ms','link 3 ms'];result=3*x;caption=`A message crosses three links taking ${x} ms each. One-way delay is ${result} ms without processing or queueing.`;formula=`delay=${x}+${x}+${x}=${result} ms`;break;
 case'database':values=[2,5,8];labels=['record A','record B','record C'];result=values.filter(v=>v>=x).length;caption=`Filter scores 2,5,8 with score ≥ ${x}. ${result} records match. The original records remain unchanged.`;formula=`SELECT * FROM scores WHERE score >= ${x}`;break;
 case'permission':values=[1,x];labels=['authenticated','owner matches'];result=x;caption=`The requester is signed in. Ownership ${x?'matches, so this own-record policy allows access':'does not match, so the server must deny access'}.`;formula=`allow = authenticated AND ownerMatches → ${!!x}`;break;
 case'accuracy':values=[x,10-x];labels=['correct','incorrect'];result=x*10;caption=`${x} correct predictions out of 10 gives ${result}% accuracy. Class balance and other errors still matter.`;formula=`accuracy=${x}/10=${result}%`;break;
 case'design':values=[x,10];labels=['prototype cost','budget limit'];result=x<=10?1:0;caption=`The prototype costs ${x}; the budget is 10. This design is ${result?'feasible on cost':'over budget'}. Other design requirements must also pass.`;formula=`cost ≤ budget → ${!!result}`;break;
 case'torque':values=[x,2,2*x];labels=['force N','arm m','torque N·m'];result=2*x;caption=`A perpendicular ${x} N force acts 2 m from the pivot, producing ${result} N·m of torque.`;formula=`τ=rF=2×${x}=${result} N·m`;break;
 case'series':values=[2,x,2+x];labels=['first Ω','second Ω','total Ω'];result=6/(2+x);caption=`Series resistances 2 Ω and ${x} Ω total ${2+x} Ω. A 6 V ideal source produces ${result.toFixed(3)} A.`;formula=`I=6/(2+${x})=${result.toFixed(3)} A`;break;
 case'sensor':values=[x,2*x+2];labels=['distance cm','sensor units'];result=2*x+2;caption=`At ${x} cm, the calibrated model reads ${result} units. The offset is 2, and each centimetre adds 2 units.`;formula=`reading=2×${x}+2=${result}`;break;
 case'control':values=Array.from({length:x+1},(_,i)=>10-8*0.5**i);labels=values.map((_,i)=>'step '+i);result=values.at(-1);caption=`With target 10, starting position 2, and gain 0.5, update ${x} reaches ${result}. Remaining error is ${10-result}.`;formula=`yₖ=10−8(0.5)^k; eₖ=8(0.5)^k`;break;
 case'automation':values=[x,30];labels=['moisture','start threshold'];result=x<30?1:0;caption=`For a pump initially off, moisture ${x} ${result?'starts watering because it is below 30':'keeps it off because it is not below 30'}. Missing data would force off.`;formula=`if valid && moisture < 30: pump ON; else OFF`;break;
 case'sequence':values=Array.from({length:x},(_,i)=>3+4*i);labels=values.map((_,i)=>'n='+(i+1));result=values.at(-1);caption=`Under the add-four rule, term ${x} is ${result}. This is a chosen arithmetic model, not the only rule fitting a few observations.`;formula=`aₙ=3+(n−1)4; a${x}=${result}`;break;
 case'logic':{const p=x>=2,q=x%2===1;values=[Number(p),Number(q)];labels=['P','Q'];result=Number(!p||q);caption=`P is ${p}, Q is ${q}. “If P then Q” is ${!!result}. Only true P with false Q violates the conditional.`;formula=`P→Q ≡ ¬P∨Q`;break;}
 case'flow':values=[x,5];labels=['input a','input b'];result=Math.max(x,5);caption=`Compare ${x} > 5. Follow ${x>5?'yes and return the first input':'no and return the second input'}. Output: ${result}.`;formula=`a>b ? a : b → ${result}`;break;
 case'data':values=[2,4,x];labels=['reading 1','reading 2','reading 3'];result=(6+x)/3;caption=`The readings total ${6+x}. Their mean is ${result.toFixed(2)}. Moving one observation shifts the mean.`;formula=`mean=(2+4+${x})/3=${result.toFixed(2)}`;break;
 case'sampling':values=[2,6,...Array(x).fill(4)];labels=values.map((_,i)=>'sample '+(i+1));result=4;caption=`Adding ${x} observations equal to 4 keeps this constructed sample mean at 4. More data alone does not prove a sample is representative.`;formula=`mean=(8+4×${x})/(2+${x})=4`;break;
 case'optimization':values=[10+4*x,14+2*x];labels=['route A score','route B score'];result=values[0]-values[1];caption=`With cost weight ${x}, route A scores ${values[0]} and B scores ${values[1]}. Lower is better: ${result===0?'they tie':result<0?'A wins':'B wins'}.`;formula=`score=time+${x}×cost`;break;
 }
 return {values,labels,result,caption,formula};
}
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function modelVisual(id,x,age,moving=false){const r=computeModel(id,x);let drawing='';const max=Math.max(1,...r.values),blue='#2264e5',amber='#f5b64c';
 if(id==='particles'){drawing=Array.from({length:12},(_,i)=>{const px=x===0?210+(i%4)*35:x===1?180+(i%4)*55+(i%2)*12:60+(i*137)%480;const py=x===0?70+Math.floor(i/4)*35:x===1?90+Math.floor(i/4)*30:35+(i*67)%150;return `<circle class="${moving?'particle-motion':''}" cx="${px}" cy="${py}" r="10" fill="${blue}"/>`}).join('')}
 else if(id==='earth'){const a=x/24*2*Math.PI;drawing=`<circle cx="70" cy="110" r="40" fill="${amber}"/><path d="M120 75h100m-100 35h100m-100 35h100" stroke="${amber}" stroke-width="3"/><circle cx="340" cy="110" r="75" fill="${blue}"/><path d="M340 35a75 75 0 0 1 0 150Z" fill="#142c4e"/><circle cx="${340-70*Math.cos(a)}" cy="${110+70*Math.sin(a)}" r="8" fill="white"/><text x="440" y="115" fill="#172f50" font-size="20">${r.result}°</text>`}
 else if(id==='area'){drawing=Array.from({length:x*3},(_,i)=>`<rect x="${70+i%x*48}" y="${30+Math.floor(i/x)*48}" width="45" height="45" fill="${blue}" stroke="white"/>`).join('')}
 else if(id==='fraction'||id==='probability'||id==='energy'||id==='memory'||id==='accuracy'||id==='binary'){const count=id==='fraction'?8:id==='probability'?6:id==='memory'?16:id==='binary'?4:10;drawing=Array.from({length:count},(_,i)=>`<rect x="${45+(i%8)*65}" y="${55+Math.floor(i/8)*75}" width="50" height="50" rx="8" fill="${(id==='binary'?r.values[i]>0:i<x)?blue:'#e1e8f1'}" stroke="#92a4bd"/><text x="${70+(i%8)*65}" y="${87+Math.floor(i/8)*75}" text-anchor="middle" fill="${(id==='binary'?r.values[i]>0:i<x)?'white':'#344d70'}" font-size="18">${id==='binary'?r.labels[i]:i+1}</text>`).join('')}
 else if(id==='place'){drawing=`<text x="70" y="38" fill="#172f50" font-size="16">Tens</text>${Array.from({length:Math.floor(x/10)},(_,i)=>`<rect x="${65+i*24}" y="55" width="18" height="115" rx="4" fill="${blue}"/>`).join('')}<text x="350" y="38" fill="#172f50" font-size="16">Ones</text>${Array.from({length:x%10},(_,i)=>`<circle cx="${355+i%5*35}" cy="${75+Math.floor(i/5)*45}" r="12" fill="${amber}"/>`).join('')}`}
 else if(['condition','permission','logic','automation','flow'].includes(id)){drawing=`<rect x="40" y="75" width="120" height="60" rx="8" fill="#edf3ff" stroke="${blue}"/><text x="100" y="110" text-anchor="middle" font-size="17">Input ${x}</text><path d="M170 105H230m130 0h60" stroke="${blue}" stroke-width="3"/><path d="M300 45 360 105 300 165 240 105Z" fill="${amber}"/><text x="300" y="112" text-anchor="middle" font-size="18">Check</text><rect x="430" y="75" width="120" height="60" rx="8" fill="${blue}"/><text x="490" y="110" fill="white" text-anchor="middle" font-size="17">${id==='flow'?r.result:r.result?'Yes / On':'No / Off'}</text>`}
 else{const width=Math.min(90,440/Math.max(1,r.values.length));drawing=`<path d="M50 15V180H565" fill="none" stroke="#8ba0bd"/>`+r.values.map((v,i)=>{const h=v/max*130,px=65+i*(480/Math.max(1,r.values.length));return `<rect class="model-bar" x="${px}" y="${180-h}" width="${width-10}" height="${h}" fill="${i===r.values.length-1?amber:blue}"/><text x="${px+(width-10)/2}" y="${170-h}" text-anchor="middle" font-size="15">${Number(v.toFixed(2))}</text><text x="${px+(width-10)/2}" y="205" text-anchor="middle" font-size="${r.values.length>6?10:12}">${e(r.labels[i]||'')}</text>`}).join('')}
 return `<div class="course-model ${age==='primary'?'story-model':''}" role="figure" aria-label="${e(r.caption)}"><svg viewBox="0 0 600 230" aria-hidden="true">${drawing}</svg><p class="model-caption">${e(r.caption)}</p>${age!=='primary'?`<code>${e(r.formula)}</code>`:''}</div>`;
}
